// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.28;

import { Types } from "@rhinestone/compact-utils/src/types/OrderTypes.sol";

/**
 * @title IPermit2IntentExecutor
 * @notice Interface for Permit2-based intent execution
 * @dev Defines the contract interface for executing intents using Permit2 for gasless approvals
 */
interface IPermit2IntentExecutor {
    /// @notice Thrown when Permit2 signature validation fails
    error InvalidPermit2Signature();

    /**
     * @notice Core Permit2 parameters for intent execution
     * @dev Contains essential Permit2 data for signature validation and replay protection
     */
    struct EIP712Permit2Stub {
        /// @dev Nonce for replay protection
        uint256 nonce;
        /// @dev Expiration timestamp for the permit
        uint256 expires;
    }

    /**
     * @notice Mandate-specific parameters for Permit2 intent execution
     * @dev Contains hashed operation and token data for the intent mandate
     */
    struct EIP712Permit2MandateStub {
        /// @dev Hash of input token details
        bytes32 tokenInHash;
        /// @dev Minimum gas required for execution of operations
        uint128 minGas;
        /// @dev Hash of target attributes (account, tokenOut, chain, expires)
        bytes32 targetAttributesHash;
        /// @dev Hash of destination operations to execute
        bytes32 destOpsHash;
        /// @dev Hash of qualifier data specific to this mandate
        bytes32 qHash;
    }

    /**
     * @notice Mandate-specific parameters for Permit2 destination chain execution
     * @dev Contains all data needed to reconstruct the mandate hash for destination chain
     *      execution verification. Includes the nested Target struct for fill parameters.
     */
    struct EIP712Permit2MandateDestinationStub {
        /// @dev Original sponsor address from the origin chain
        address sponsor;
        /// @dev Arbiter that facilitated the cross-chain transfer
        address arbiter;
        /// @dev Minimum gas required for pre-claim operations
        uint128 minGas;
        /// @dev Chain ID where the order was originally notarized
        uint256 notarizedChainId;
        /// @dev Hash of pre-claim operations from origin chain
        bytes32 preClaimOpsHash;
        /// @dev Hash of input token details
        bytes32 tokenInHash;
        /// @dev Hash of qualifier data
        bytes32 qHash;
        /// @dev Target parameters for fill validation
        Target targetStub;
    }

    /**
     * @notice Target chain fill parameters for Permit2 destination execution
     * @dev Contains minimal parameters needed to validate the fill on destination chain
     */
    struct Target {
        /// @dev Deadline timestamp for completing the fill
        uint256 fillExpiry;
        /// @dev Hash of expected output tokens
        bytes32 tokenOutHash;
    }

    /**
     * @notice Executes pre-claim operations using Permit2-based authorization
     * @dev Validates Permit2 signature and executes operations before any cross-chain transfers
     * @param account The user account that signed the intent
     * @param permit2Stub Core Permit2 parameters including nonce and expiration
     * @param mandateStub Mandate-specific parameters with operation and token hashes
     * @param preClaimOps Array of operations to execute on the origin chain
     * @param signature EIP-712 signature from the account authorizing the operations
     * @return permit2Hash The computed Permit2 hash used for signature validation
     */
    function executePreClaimOpsWithPermit2Stub(
        address account,
        EIP712Permit2Stub calldata permit2Stub,
        EIP712Permit2MandateStub calldata mandateStub,
        Types.Operation calldata preClaimOps,
        bytes calldata signature
    )
        external
        returns (bytes32 permit2Hash);

    /**
     * @notice Executes target operations using Permit2-based authorization
     * @dev Validates Permit2 signature and executes operations on the destination chain
     * @param account The user account that signed the intent
     * @param permit2Stub Core Permit2 parameters including nonce and expiration
     * @param mandateStub Mandate-specific parameters with operation and token hashes
     * @param targetOps Array of operations to execute on the destination chain
     * @param signature EIP-712 signature from the account authorizing the operations
     * @return permit2Hash The computed Permit2 hash used for signature validation
     */
    function executeTargetOpsWithPermit2Stub(
        address account,
        EIP712Permit2Stub calldata permit2Stub,
        EIP712Permit2MandateDestinationStub calldata mandateStub,
        Types.Operation calldata targetOps,
        bytes calldata signature
    )
        external
        returns (bytes32 permit2Hash);

    /**
     * @notice Checks if a nonce has been used for a specific account
     * @dev Provides a way to check nonce usage for Permit2 intents
     * @param nonce The nonce value to check
     * @param account The account address that owns the nonce
     * @return used True if the nonce has been consumed, false otherwise
     */
    function isPermit2IntentNonceConsumed(uint256 nonce, address account) external view returns (bool used);
}

src/base/arbiter/Permit2Arbiter/Permit2A.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.28;

import { ISignatureTransfer } from "permit2/src/interfaces/ISignatureTransfer.sol";
import { Types } from "@rhinestone/compact-utils/src/types/OrderTypes.sol";
import { SmartExecutionLib } from "@rhinestone/compact-utils/src/common/SmartExecutionLib.sol";
import { Permit2Lib } from "./lib/Permit2Lib.sol";

/**
 * @title Permit2Arbiter
 * @notice Abstract base contract providing Permit2 protocol integration for signature-based token transfers
 * @dev This contract serves as the integration layer with Uniswap's Permit2 protocol, enabling arbiters
 *      to execute token transfers using cryptographic signatures instead of traditional allowances.
 *
 *      Permit2 is a token approval management protocol that allows users to grant token spending permissions
 *      through signatures rather than on-chain approvals. This provides better UX and gas efficiency by:
 *      - Eliminating the need for separate approval transactions
 *      - Enabling batch token transfers with single signature
 *      - Providing fine-grained control over token permissions with nonces and deadlines
 *
 *      Integration with Router ecosystem:
 *      - Processes token inputs from cross-chain orders using signature-based permissions
 *      - Converts order token data into Permit2-compatible permission structures
 *      - Handles witness-based transfers where mandate hashes serve as additional validation
 *      - Enables seamless token unlocking as part of cross-chain settlement flows
 *
 *      The contract abstracts Permit2's complexity while providing standardized interfaces for
 *      settlement-specific arbiters to execute secure, signature-authorized token transfers.
 *
 *      Security considerations:
 *      - All transfers require valid signatures from token owners (sponsors)
 *      - Mandate hashes provide additional witness-based validation for cross-chain operations
 *      - Nonce and deadline parameters prevent replay attacks and ensure time-bounded permissions
 *      - Permit2's battle-tested signature validation provides cryptographic security guarantees
 *
 *      Gas optimization notes:
 *      - Batch operations automatically process multiple tokens in single transaction
 *      - Immutable Permit2 interface minimizes storage costs
 *      - Signature-based transfers eliminate separate approval gas costs
 * @custom:security Signature validation relies on Permit2's implementation - ensure valid Permit2 address
 */
abstract contract Permit2Arbiter {
    using SmartExecutionLib for Types.Operation;
    using SmartExecutionLib for bytes;
    using Permit2Lib for uint256[2][];

    /// @notice Permit2 signature transfer interface for executing signature-based token transfers
    /// @dev This immutable interface provides access to Permit2's signature transfer functionality,
    ///      enabling secure token transfers through cryptographic signatures rather than allowances.
    ///      Used for all signature-based token unlocking operations in the arbiter system.
    ISignatureTransfer internal immutable PERMIT2;

    /**
     * @notice Initializes the Permit2Arbiter with Permit2 protocol integration
     * @dev Sets up the immutable interface to Uniswap's Permit2 contract for signature-based
     *      token transfers. This interface enables the arbiter to process token transfers using
     *      cryptographic signatures instead of traditional token allowances.
     * @param permit2 The address of the Permit2 SignatureTransfer contract on the current network.
     *                Must be the canonical Permit2 deployment to ensure signature compatibility
     *                and security. The address is different on each network but maintains the same interface.
     * @custom:security The permit2 address cannot be changed after deployment - verify it matches
     *                  the official Permit2 deployment for the target network
     */
    constructor(address permit2) {
        PERMIT2 = ISignatureTransfer(permit2);
    }

    /**
     * @notice Unlocks tokens using Permit2 signature-based transfers with mandate witness validation
     * @dev Processes token inputs from a cross-chain order by converting them into Permit2-compatible
     *      permission structures and executing signature-authorized transfers. The mandate hash serves
     *      as a witness to provide additional validation that the transfer is part of a valid cross-chain
     *      settlement operation.
     *
     *      The function performs the following operations:
     *      1. Converts order token data (id/amount pairs) into Permit2 TokenPermissions
     *      2. Creates SignatureTransferDetails specifying the depositor as recipient
     *      3. Constructs a PermitBatchTransferFrom with order nonce and expiry
     *      4. Executes permitWitnessTransferFrom with mandate hash as witness data
     *
     *      This enables secure token transfers where:
     *      - The sponsor (token owner) has pre-signed permission for the transfer
     *      - The mandate hash proves the transfer is part of a valid cross-chain order
     *      - The depositor receives the tokens as specified in the settlement
     *      - Nonce prevents replay attacks and expiry ensures time-bounded permissions
     * @param order The cross-chain order containing token inputs, sponsor, nonce, and expiry details.
     *              The tokenIn array contains [token_id, amount] pairs that get converted to token addresses.
     * @param sig The signature from the order sponsor authorizing the Permit2 token transfer.
     *            Must be a valid EIP-712 signature over the permit data and mandate witness.
     * @param mandateHash The hash of the cross-chain mandate serving as witness data for additional validation.
     *                    This proves the transfer is part of a legitimate cross-chain settlement operation.
     * @param depositor The address that will receive the transferred tokens. Typically the settlement
     *                  contract or final recipient depending on the settlement flow.
     * @custom:security The signature must be from the order sponsor and include the mandate hash witness
     * @custom:gas Uses batch operations when multiple tokens are present for optimal gas efficiency
     */
    function _unlockPermit2(Types.Order calldata order, bytes calldata sig, bytes32 mandateHash, address depositor) internal {
        // Convert order token data into Permit2-compatible permission structures
        // This transforms [token_id, amount] pairs into proper token addresses and amounts
        (
            ISignatureTransfer.TokenPermissions[] memory tokenPermission,
            ISignatureTransfer.SignatureTransferDetails[] memory signatureTransferDetails
        ) = order.tokenIn.toTokenPermissions(depositor);

        // Create the permit structure with order-specific nonce and expiry
        // The nonce prevents replay attacks while expiry ensures time-bounded permissions
        ISignatureTransfer.PermitBatchTransferFrom memory permit =
            ISignatureTransfer.PermitBatchTransferFrom({ permitted: tokenPermission, nonce: order.nonce, deadline: order.expires });

        // Execute the signature-based transfer with mandate hash as witness
        // The witness mechanism provides additional validation beyond basic token permissions
        PERMIT2.permitWitnessTransferFrom({
            permit: permit,
            transferDetails: signatureTransferDetails,
            owner: order.sponsor, // The original token owner who signed the permit
            witness: mandateHash, // Cross-chain mandate hash for additional validation
            witnessTypeString: Permit2Lib.WITNESS_TYPESTRING, // EIP-712 typestring for witness validation
            signature: sig // Sponsor's signature authorizing the transfer
        });
    }
}

