     * @return rawClaimPtr The raw pointer to the exogenous batch multichain claim.
     */
    function asRawPtr(ExogenousBatchMultichainClaim calldata claim) internal pure returns (uint256 rawClaimPtr) {
        assembly {
            rawClaimPtr := claim
        }
    }
}

